import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { useNavigate } from 'react-router-dom';
import '../../visualPage/CadastroSalas.css';

const CadastroSalas = () => {
  const navigate = useNavigate();
  
  const [numeroSala, setNumeroSala] = useState('');
  const [capacidade, setCapacidade] = useState('');
  const [dataCadastro, setDataCadastro] = useState('');
  const [salas, setSalas] = useState([]);
  const [salaSelecionada, setSalaSelecionada] = useState(null); // Estado para a sala selecionada

  const [canEdit, setCanEdit] = useState(false);
  const [canDelete, setCanDelete] = useState(false);
  const [canConsult, setCanConsult] = useState(true);
  const [canCreate, setCanCreate] = useState(true);

  useEffect(() => {
    fetchSalas();
  }, []);

  const fetchSalas = async () => {
    try {
      const response = await axios.get('http://localhost:5000/api/salas');
      console.log('Salas recebidas:', response.data); // Log para verificar os dados

      setSalas(response.data);

      // Se houver salas, seleciona a primeira ativa
      if (response.data.length > 0) {
        const primeiraSalaAtiva = response.data[0]; // Assumindo que a primeira sala é a ativa
        setSalaSelecionada(primeiraSalaAtiva); // Define a sala selecionada
        setNumeroSala(primeiraSalaAtiva.numeroSala);
        setCapacidade(primeiraSalaAtiva.capacidade);
        setDataCadastro(primeiraSalaAtiva.dataCadastro);
      }
    } catch (err) {
      console.error('Erro ao consultar salas:', err);
    }
  };

  const handleCreateNewSala = async () => {
    // (código para criar uma nova sala)
  };

  const handleEditSala = async (id) => {
    // (código para editar uma sala)
  };

  const handleDeleteSala = async (id) => {
    // (código para excluir uma sala)
  };

  const handleConsultSalas = () => {
    navigate('/consulta/salas');
  };

  return (
    <div className="container-cadastro-salas">
      <h2>Cadastro de Sala</h2>

      <div>
        <input
          type="text"
          placeholder="Número da Sala"
          value={numeroSala}
          onChange={(e) => setNumeroSala(e.target.value)}
        />
        <input
          type="number"
          placeholder="Capacidade"
          value={capacidade}
          onChange={(e) => setCapacidade(e.target.value)}
        />
        <input
          type="date"
          placeholder="Data de Cadastro"
          value={dataCadastro}
          onChange={(e) => setDataCadastro(e.target.value)}
        />

        <button onClick={handleCreateNewSala} disabled={!canCreate}>Cadastrar</button>
      </div>

      <div>
        <h3>Salas Cadastradas</h3>
        <ul>
          {salas.map(sala => (
            <li key={sala.id}>
              Sala {sala.numeroSala} - Capacidade: {sala.capacidade}
              <button onClick={() => {
                setSalaSelecionada(sala);
                setNumeroSala(sala.numeroSala);
                setCapacidade(sala.capacidade);
                setDataCadastro(sala.dataCadastro);
              }} disabled={!canEdit}>Editar</button>
              <button onClick={() => handleDeleteSala(sala.id)} disabled={!canDelete}>Excluir</button>
            </li>
          ))}
        </ul>
      </div>

      <div>
        <button onClick={handleConsultSalas} disabled={!canConsult}>Consultar Salas</button>
      </div>
    </div>
  );
};

export default CadastroSalas;
